import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        T = int(t_str)
    except StopIteration:
        return

    for _ in range(T):
        try:
            S = next(iterator)
            P = next(iterator)
        except StopIteration:
            break

        if len(P) != 2 * len(S):
            print("Impossible")
            continue

        found = False
        n = len(S)
        for i in range(n + 1):
            candidate = S[:i] + S + S[i:]
            if candidate == P:
                found = True
                break

        if found:
            print("Possible")
        else:
            print("Impossible")

if __name__ == "__main__":
    solve()
